class Solution {
    std::unordered_map<int, int> freq;
    int best = 0;
    int dfs(TreeNode* node) {
        if (!node) return 0;
        int sum = node->val + dfs(node->left) + dfs(node->right);
        best = std::max(best, ++freq[sum]);
        return sum;
    }
public:
    std::vector<int> findFrequentTreeSum(TreeNode* root) {
        freq.clear(); best = 0;
        dfs(root);
        std::vector<int> ans;
        for (const auto& p : freq) if (p.second == best) ans.push_back(p.first);
        return ans;
    }
};
